protected void startArray(String name){
  JsonValue value=new JsonValue(ValueType.array);
  if (current != null) {
    try {
      addChild(name,value);
    } catch (RuntimeException e) {
      // Log exception for debugging; then skip further processing
      System.err.println("Exception in addChild: " + e.getMessage());
      return;
    }
  }
  elements.add(value);
  current=value;
}
